# Generated by manage.py generate_test_cases.
"""Exercise reusable booking configuration and multiple destination calendars."""

import json
from unittest.mock import patch

from django.contrib.contenttypes.models import ContentType
from django.core.exceptions import PermissionDenied, ValidationError
from django.test import RequestFactory

from bloomerp.forms.model_form import bloomerp_modelform_factory
from bloomerp.models import ApplicationField
from bloomerp.models.communication.calendar import BookingLink
from bloomerp.models.communication.email_account import EmailAccount
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import CalendarFixtures


class TestBookingLinkModel(CalendarFixtures, BloomerpModelTestCase):
    model = BookingLink

    def get_test_scenarios(self) -> list[ModelScenario[BookingLink]]:
        """Cover destinations, availability and the conditional email message."""
        scenarios = [
            ModelScenario(
                name="Destinations do not infer a host or organizer",
                preparation=self.prepare,
                create_args=self.booking_args,
                post_create=self.set_destinations,
                create_validators=self.has_destinations,
            )
        ]
        scenarios.extend(
            [
                ModelScenario(
                    name="An existing link can keep its legacy availability when edited",
                    preparation=self.prepare,
                    create_args=self.legacy_schedule_args,
                    create_validators=self.unchanged_legacy_schedule_is_preserved,
                ),
                ModelScenario(
                    name="Zero duration",
                    preparation=self.prepare,
                    create_args=self.zero_duration,
                    expected_exceptions=[
                        ExpectedModelException("create", ValidationError)
                    ],
                ),
                ModelScenario(
                    name="Invalid availability timezone",
                    preparation=self.prepare,
                    create_args=self.invalid_timezone,
                    expected_exceptions=[
                        ExpectedModelException("create", ValidationError)
                    ],
                ),
                ModelScenario(
                    name="Choosing an email account requires a nonblank message",
                    preparation=self.prepare_email_account,
                    create_args=self.booking_with_blank_message,
                    expected_exceptions=[
                        ExpectedModelException("create", ValidationError, "Enter an email message"),
                    ],
                ),
                ModelScenario(
                    name="A draft email message can be kept after clearing its account",
                    preparation=self.prepare_email_account,
                    create_args=self.booking_with_email_settings,
                    update_args={"email_account": None},
                    update_validators=self.retains_draft_message,
                ),
                ModelScenario(
                    name="Editing the confirmation message requires access to its sender",
                    preparation=self.prepare_email_account,
                    create_args=self.booking_with_email_settings,
                    create_validators=self.cannot_change_inaccessible_sender_message,
                ),
            ]
        )
        return scenarios

    def prepare_email_account(self) -> None:
        """Add a sender to the existing booking model fixtures."""
        self.prepare()
        self.email_account = EmailAccount.objects.create(email_address="host@example.com")

    def booking_with_blank_message(self) -> dict[str, object]:
        """Try saving a selected account with a whitespace-only message."""
        return self.booking_args(email_account=self.email_account, email_message=" \t\n")

    def booking_with_email_settings(self) -> dict[str, object]:
        """Create an offering with a sender and an email message."""
        return self.booking_args(
            email_account=self.email_account, email_message="See you at your appointment."
        )

    def retains_draft_message(self, booking: BookingLink) -> bool:
        """Keep the text as a draft when the sender is cleared."""
        return booking.email_account_id is None and booking.email_message == "See you at your appointment."

    def cannot_change_inaccessible_sender_message(self, booking: BookingLink) -> bool:
        """Allow regular edits while preventing an editor from repurposing the sender."""
        request = RequestFactory().post("/")
        request.user = self.user
        with patch("bloomerp.middleware.current_request", return_value=request):
            booking.title = "Updated availability"
            booking.save(update_fields=["title"])
            booking.email_message = "Unapproved message"
            with self.assertRaisesMessage(PermissionDenied, "You cannot use the selected email account."):
                booking.save(update_fields=["email_message"])
        booking.refresh_from_db()
        return booking.title == "Updated availability" and booking.email_message == "See you at your appointment."

    def set_destinations(self, booking: BookingLink) -> None:
        """Assign all destination calendars instead of choosing one from a pool."""
        booking.target_inboxes.add(self.inbox, self.team_inbox)

    def has_destinations(self, booking: BookingLink) -> bool:
        """Verify retained description, independent random tokens, and all destinations."""
        return (
            booking.target_inboxes.count() == 2
            and booking.organizing_inbox_id == self.inbox.pk
            and booking.public_token != self.booking.public_token
            and booking.description == "Discuss your project"
        )

    def zero_duration(self) -> dict[str, object]:
        """Attempt a booking duration that cannot describe a meeting."""
        return self.booking_args(meeting_duration_minutes=0)

    def invalid_timezone(self) -> dict[str, object]:
        """Attempt an unresolved timezone instead of guessing its offset."""
        return self.booking_args(timezone="Not/AZone")

    def legacy_schedule_args(self) -> dict[str, object]:
        """Create an arbitrary schedule saved before the structured editor existed."""
        return self.booking_args(availability_hours={"legacy_schedule": ["weekdays"]})

    def unchanged_legacy_schedule_is_preserved(self, booking: BookingLink) -> bool:
        """Keep unchanged JSON but validate changes to the saved schedule."""
        ApplicationField.objects.get_or_create(
            content_type=ContentType.objects.get_for_model(BookingLink),
            field="availability_hours",
            defaults={"field_type": "JSONField"},
        )
        form_class = bloomerp_modelform_factory(BookingLink, fields=["availability_hours"])
        form = form_class(
            instance=booking,
            data={"availability_hours": json.dumps(booking.availability_hours)},
        )
        changed = form_class(instance=booking, data={"availability_hours": '{"legacy_schedule": ["weekends"]}'})
        self.assertTrue(form.is_valid(), form.errors)
        self.assertEqual(form.changed_data, [])
        self.assertEqual(form.cleaned_data.get("availability_hours"), booking.availability_hours)
        self.assertIn("availability_hours", changed.errors)
        return True
